import Foundation

// CI/CD Pipeline Notification Service
// Sends build status emails and maintains audit logs

struct AuditEntry: Codable {
    let timestamp: Date
    let action: String
    let actor: String
    let details: String
}

class AuditLogger {
    private var entries: [AuditEntry] = []
    private let logFile: String

    init(logFile: String = "/var/log/cicd/audit.json") {
        self.logFile = logFile
    }

    func log(action: String, actor: String, details: String) {
        let entry = AuditEntry(
            timestamp: Date(),
            action: action,
            actor: actor,
            details: details
        )
        entries.append(entry)
        persistEntry(entry)
    }

    private func persistEntry(_ entry: AuditEntry) {
        // Append to audit log file
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        guard let data = try? encoder.encode(entry),
              let json = String(data: data, encoding: .utf8) else { return }
        let line = json + "\n"
        if let handle = FileHandle(forWritingAtPath: logFile) {
            handle.seekToEndOfFile()
            handle.write(line.data(using: .utf8)!)
            handle.closeFile()
        }
    }
}

protocol HeaderEncoder {
    func encode(key: String, value: String) -> String
}

// RFC 2047 encoded-word encoder for non-ASCII content
class MIMEHeaderEncoder: HeaderEncoder {
    func encode(key: String, value: String) -> String {
        let sanitized = sanitizeHeaderValue(value)
        return "\(key): \(sanitized)"
    }

    private func sanitizeHeaderValue(_ value: String) -> String {
        // Remove bare CR and LF that aren't part of CRLF folding
        var result = value
        result = result.replacingOccurrences(of: "\r\n", with: " ")
        result = result.replacingOccurrences(of: "\r", with: "")
        result = result.replacingOccurrences(of: "\n", with: "")
        return result
    }
}

class NotificationAddress {
    let displayName: String
    let email: String

    init(displayName: String, email: String) {
        self.displayName = displayName
        self.email = email
    }

    // Format as RFC 5322 mailbox: "Display Name" <email@example.com>
    func formatted(encoder: HeaderEncoder) -> String {
        if displayName.isEmpty {
            return email
        }
        return "\"\(displayName)\" <\(email)>"
    }
}

struct BuildResult {
    let projectName: String
    let branch: String
    let commitAuthor: String
    let commitMessage: String
    let status: String
    let buildNumber: Int
}

class PipelineNotifier {
    private let encoder: HeaderEncoder
    private let auditLogger: AuditLogger
    private let smtpHost: String
    private let fromAddress: String

    init(smtpHost: String = "smtp.internal.corp",
         fromAddress: String = "cicd@builds.internal.corp") {
        self.encoder = MIMEHeaderEncoder()
        self.auditLogger = AuditLogger()
        self.smtpHost = smtpHost
        self.fromAddress = fromAddress
    }

    func notifyBuildComplete(result: BuildResult, recipients: [String]) {
        let subject = "[\(result.status)] \(result.projectName) #\(result.buildNumber) - \(result.branch)"
        let body = buildEmailBody(result: result)

        // Construct recipient from commit metadata
        let authorAddress = NotificationAddress(
            displayName: result.commitAuthor,
            email: recipients.first ?? "team@internal.corp"
        )

        let headers = buildHeaders(
            subject: subject,
            to: authorAddress,
            replyTo: result.commitAuthor
        )

        sendEmail(headers: headers, body: body)

        auditLogger.log(
            action: "build_notification_sent",
            actor: "pipeline",
            details: "Notified \(recipients.count) recipients for \(result.projectName) #\(result.buildNumber)"
        )
    }

    private func buildHeaders(subject: String, to: NotificationAddress, replyTo: String) -> [String] {
        var headers: [String] = []

        headers.append(encoder.encode(key: "From", value: fromAddress))
        headers.append(encoder.encode(key: "To", value: to.formatted(encoder: encoder)))
        headers.append(encoder.encode(key: "Subject", value: subject))
        headers.append(encoder.encode(key: "Date", value: formatRFC2822Date()))
        headers.append(encoder.encode(key: "Message-ID", value: generateMessageId()))
        headers.append(encoder.encode(key: "X-Mailer", value: "CICD-Pipeline/2.1"))
        headers.append(encoder.encode(key: "MIME-Version", value: "1.0"))
        headers.append(encoder.encode(key: "Content-Type", value: "text/plain; charset=utf-8"))

        // Reply-To uses the commit author field directly for developer convenience
        // The author field comes from git log --format='%aN <%aE>'
        headers.append(buildReplyToHeader(replyTo: replyTo))

        return headers
    }

    private func buildReplyToHeader(replyTo: String) -> String {
        // Apply display-name encoding for internationalized names
        // The replyTo is expected to be a name or email from git metadata
        let components = parseGitAuthorField(replyTo)
        let encoded = encodeInternationalizedField(components)
        return "Reply-To: \(encoded)"
    }

    private func parseGitAuthorField(_ field: String) -> (name: String, email: String) {
        // Parse "Name <email>" format from git
        if let angleStart = field.firstIndex(of: "<"),
           let angleEnd = field.firstIndex(of: ">") {
            let name = String(field[field.startIndex..<angleStart]).trimmingCharacters(in: .whitespaces)
            let email = String(field[field.index(after: angleStart)..<angleEnd])
            return (name, email)
        }
        // If no angle brackets, treat entire field as a name
        return (field, "")
    }

    private func encodeInternationalizedField(_ components: (name: String, email: String)) -> String {
        // RFC 2047 encode the display name if it contains non-ASCII
        let name = components.name
        let needsEncoding = name.unicodeScalars.contains { $0.value > 127 }

        let encodedName: String
        if needsEncoding {
            let utf8Data = name.data(using: .utf8)!
            let base64 = utf8Data.base64EncodedString()
            encodedName = "=?UTF-8?B?\(base64)?="
        } else {
            encodedName = name
        }

        if components.email.isEmpty {
            return encodedName
        }
        return "\"\(encodedName)\" <\(components.email)>"
    }

    private func buildEmailBody(result: BuildResult) -> String {
        return """
        Build Status: \(result.status)
        Project: \(result.projectName)
        Branch: \(result.branch)
        Build #: \(result.buildNumber)

        Commit Author: \(result.commitAuthor)
        Commit Message: \(result.commitMessage)

        --
        CI/CD Pipeline Notification Service
        """
    }

    private func sendEmail(headers: [String], body: String) {
        let message = headers.joined(separator: "\r\n") + "\r\n\r\n" + body
        // In production, this connects to SMTP and sends
        deliverToSMTP(message: message)
    }

    private func deliverToSMTP(message: String) {
        // SMTP delivery implementation
        print("Delivering message (\(message.count) bytes) to \(smtpHost)")
    }

    private func formatRFC2822Date() -> String {
        let formatter = DateFormatter()
        formatter.dateFormat = "EEE, dd MMM yyyy HH:mm:ss Z"
        formatter.locale = Locale(identifier: "en_US_POSIX")
        return formatter.string(from: Date())
    }

    private func generateMessageId() -> String {
        let uuid = UUID().uuidString.lowercased()
        return "<\(uuid)@builds.internal.corp>"
    }
}
